import {regions,STATUS,countryName,defaultVisits,seedPosts} from './data.js';
import {loadState,saveState,publishedPosts,regionPosts,visitStats,validatePost,validateImport} from './store.js';
import {GITHUB,GitHubRepository,canonical,mapValue} from './github.js';
import {validateContent,loadDrafts,saveDrafts,editingPosts} from './content-model.js';
import {MAP_VIEWBOX} from './geography.js';

let state={formatVersion:2,revision:'initial',visits:{...defaultVisits},colors:{},posts:structuredClone(seedPosts)}, mapFilter='',essayFilter='all',listSearch='',mapSearch='',editorAttachments=[],editorDirty=false,toastTimer;
let session=false,repository=null,account='',drafts=loadDrafts(),repositoryState=structuredClone(state),editorBasePost=null,lastCommit=null,saving=false,ready=false,pendingMapOperation=null;
const mapEdits=new Map();
const mapCameras={cn:{x:360,y:270,zoom:1},jp:{x:360,y:275,zoom:1}};
let mapDrag=null,suppressMapClick=false;
let mapLabelsVisible=true;
const SESSION_TOKEN_KEY='fieldnotes-github-session-v2';
const main=document.querySelector('main'),dialog=document.querySelector('#dialog'),tooltip=document.querySelector('#tooltip');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const go=route=>{location.hash=route;};
const regionById=id=>regions.find(r=>r.id===id);
const statusFor=id=>STATUS[state.visits[id]||'none'];
const colorFor=id=>/^#[0-9a-f]{6}$/i.test(state.colors?.[id])?state.colors[id]:statusFor(id).color;
function isDark(hex){const [r,g,b]=[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));return r*.299+g*.587+b*.114<153;}
function persistDrafts(){try{saveDrafts(drafts);return true;}catch{toast('本机草稿空间不足，请减少照片或导出备份');return false;}}
function draftFor(id){return drafts.find(p=>p.id===id);}
function postForEdit(id){return draftFor(id)||state.posts.find(p=>p.id===id);}
function rememberDraft(post,operationId=null){const copy={...structuredClone(post),status:'draft',basePublic:editorBasePost,pendingOperationId:operationId};const index=drafts.findIndex(p=>p.id===post.id);if(index<0)drafts.push(copy);else drafts[index]=copy;return persistDrafts();}
function adoptSite(site){state=validateContent(site);repositoryState=structuredClone(state);}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
const statusPill=id=>`<span class="status-pill"><i class="swatch" style="background:${colorFor(id)}"></i>${statusFor(id).label}</span>`;
function safeImage(src){const allowed=typeof src==='string'&&(/^(assets\/[\w.-]+\.(svg|png|jpe?g|webp)|uploads\/[a-f0-9]{64}\.(jpg|png|webp))$/.test(src)||/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(src));const path=allowed?src:'assets/lake.svg';return globalThis.FIELDNOTES_ASSETS?.[path]||path;}
function safeURL(url){try{const u=new URL(url);return ['https:','http:','mailto:'].includes(u.protocol)?u.href:null;}catch{return null;}}
function sanitizeInline(html){const t=document.createElement('template');t.innerHTML=html||'';function clean(node){if(node.nodeType===Node.TEXT_NODE)return esc(node.textContent);if(node.nodeType!==Node.ELEMENT_NODE)return '';const inner=[...node.childNodes].map(clean).join('');const tag=node.tagName.toLowerCase();if(['strong','b','em','i'].includes(tag))return `<${tag}>${inner}</${tag}>`;if(tag==='br')return '<br>';if(tag==='a'){const url=safeURL(node.getAttribute('href'));return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${inner}</a>`:inner;}return inner;}return [...t.content.childNodes].map(clean).join('');}
function renderBody(body){return body.map(b=>{if(b.type==='image')return `<figure><img src="${esc(safeImage(b.src))}" alt="${esc(b.alt||'文章照片')}" loading="lazy"><figcaption>${esc(b.alt||'旅行照片')}</figcaption></figure>`;const content=b.html?sanitizeInline(b.html):esc(b.text);const tag={h2:'h2',quote:'blockquote',p:'p'}[b.type]||'p';return `<${tag}>${content}</${tag}>`;}).join('');}
function regionSVG(r,mini=false){const color=colorFor(r.id);return `<g class="region ${isDark(color)?'dark':''} ${mapFilter&&state.visits[r.id]!==mapFilter&&!(mapFilter==='none'&&!state.visits[r.id])?'is-dim':''}" data-region="${r.id}" ${mini?'':`role="link" tabindex="0" aria-label="${esc(r.full)}，${statusFor(r.id).label}，${regionPosts(state,r.id).length} 篇游记"`}><title>${esc(r.full)} · ${statusFor(r.id).label}</title><path class="region-shape" d="${mini?r.miniPath:r.path}" fill="${color}" fill-rule="evenodd" vector-effect="non-scaling-stroke"/>${mini?'':`${r.leader?`<path class="label-leader" d="M${r.anchor.join(',')}L${r.x},${r.y}"/>`:''}<text class="${r.leader||['cn-81','cn-82'].includes(r.id)?'outside-label':''}" x="${r.x}" y="${r.y}">${esc(r.name)}</text>`}</g>`;}
function mapViewBox(country){const camera=mapCameras[country],[,,w,h]=MAP_VIEWBOX[country].split(' ').map(Number);return [camera.x-w/camera.zoom/2,camera.y-h/camera.zoom/2,w/camera.zoom,h/camera.zoom].join(' ');}
function mapCard(country){const stats=visitStats(state,country);return `<section class="map-card ${country}" aria-label="${countryName(country)}旅行地图"><div class="map-card-head"><div class="country-label"><h3>${countryName(country)}</h3><span>${country==='cn'?'CHINA':'JAPAN'}</span></div><span class="map-count"><b>${stats.been}</b> / ${stats.total} 已到访</span></div><div class="map-canvas ${mapLabelsVisible?'':'hide-labels'}"><div class="map-zoom" role="group" aria-label="${countryName(country)}地图缩放"><button data-action="map-zoom" data-country="${country}" data-factor="1.5" aria-label="放大${countryName(country)}地图">＋</button><button data-action="map-zoom" data-country="${country}" data-factor="0.6666666667" aria-label="缩小${countryName(country)}地图">−</button><button data-action="map-reset" data-country="${country}" aria-label="还原${countryName(country)}地图">↺</button></div><svg data-map-country="${country}" viewBox="${mapViewBox(country)}" aria-label="${countryName(country)}各地区地理轮廓地图">${country==='cn'?'<rect class="inset-frame" x="25" y="415" width="205" height="109" rx="5"/><text class="map-annotation" x="36" y="430">港澳 · 放大</text>':'<rect class="inset-frame" x="28" y="65" width="208" height="153" rx="5"/><text class="map-annotation" x="42" y="83">冲绳 · 附图</text>'}${regions.filter(r=>r.country===country).map(r=>regionSVG(r)).join('')}</svg></div><div class="map-bottom"><span>点击地区阅读游记 · 放大后可拖动查看</span><span class="map-coordinate">${country==='cn'?'34 省级地区':'47 都道府县'}</span></div></section>`;}
function atlasSection(full=false){const stats=visitStats(state);return `<section class="atlas-section" id="atlas"><div class="section-heading"><div><div class="eyebrow">A LITTLE FURTHER, A LITTLE CLOSER</div><h2>把走过的地方，慢慢点亮。</h2></div>${full?'<a class="text-link" href="#/admin/maps">管理我的足迹 ↗</a>':'<a href="#/atlas" class="right-note">展开旅行地图 ↗</a>'}</div><div class="atlas-tools"><div class="legend" aria-label="按足迹状态筛选">${Object.entries(STATUS).map(([key,s])=>`<button data-action="filter-map" data-value="${key}" aria-pressed="${mapFilter===key}"><i class="swatch" style="background:${s.color}"></i>${s.label}</button>`).join('')}<button data-action="filter-map" data-value="" aria-pressed="${!mapFilter}">全部</button></div><div class="atlas-options"><label><input type="checkbox" id="show-labels" ${mapLabelsVisible?'checked':''}>显示地名</label><span>颜色里，藏着我的旅行记忆</span></div></div><div class="map-grid">${mapCard('cn')}${mapCard('jp')}</div><div class="atlas-summary"><span>已点亮 <b>${stats.been}</b> / ${stats.total} 个地区 · <b>${stats.wish}</b> 个想去的地方${mapFilter?' · 当前突出：'+STATUS[mapFilter].label:''}</span><span>地理轮廓 · Natural Earth</span></div></section>`;}
function postCard(p){const location=p.regions.map(id=>regionById(id)?.name).filter(Boolean).join(' · ');return `<a class="post-card" href="#/post/${encodeURIComponent(p.id)}"><div class="post-image"><img src="${esc(safeImage(p.cover))}" alt="${esc(p.title)}封面" loading="lazy"></div><div><div class="post-meta"><span class="category">${p.type==='travel'?'旅行手记':'日常随笔'}</span><span>·</span>${location?`<span>${esc(location)}</span><span>·</span>`:''}<time>${esc(p.date.replaceAll('-','.'))}</time></div><h3>${esc(p.title)}</h3><p>${esc(p.excerpt)}</p><span class="read-more">读一读 <span aria-hidden="true">↗</span></span></div></a>`;}
function home(){return `<section class="hero"><div><div class="eyebrow">A PERSONAL SPACE FOR IDEAS & JOURNEYS</div><h1>认真研究，<br><em>也认真生活。</em></h1><p>这里收藏想明白的事，也收藏路上偶遇的风景。<br>从学术笔记到旅途碎片，慢慢把世界写成自己的地图。</p><div class="hero-actions"><a class="button" href="#/atlas">翻开旅行地图 <span>↗</span></a><a class="text-link" href="#/academic">认识学术里的我 ↗</a></div><div class="prototype-line">文章与足迹保存于 GitHub · 部分初始内容为示例</div></div><div class="postcard"><img src="assets/kyoto.svg" alt="京都街巷主题旅行插画"><div class="postcard-caption">在路上，也在生活里。<span>35°00′ N / 135°46′ E</span></div><div class="postcard-stamp">山海之间<br>COLLECT MOMENTS</div><div class="postcard-note">旅の途中 · 旅途未完</div></div></section>${atlasSection()}<section class="section-spacer"><div class="section-heading"><div><div class="eyebrow">RECENT FIELDNOTES</div><h2>最近，写了这些。</h2></div><a class="text-link" href="#/essays">所有文章 ↗</a></div><div class="post-grid">${publishedPosts(state).slice(0,3).map(postCard).join('')}</div></section><section class="home-bottom"><div><div class="tiny-label">THE PERSON BEHIND THE NOTES</div><h3>你好，欢迎来到我的小小空间。</h3><p>这里的一半留给研究与思考，另一半留给旅行和生活。姓名、简介与研究方向，可以在仓库中替换为你自己的故事。</p><a href="#/academic">去学术主页看看 <span>↗</span></a></div><div><div class="tiny-label">GOOD PLACES ON THE INTERNET</div><h3>一些值得停留的地方。</h3><p>朋友的博客、常读的网站，以及偶然发现的好东西。在互联网上，留一扇通往彼此的窗。</p><a href="#/links">打开友情链接 <span>↗</span></a></div></section>`;}
function atlasPage(){return `<div class="page-head"><div class="eyebrow">MY TRAVEL ATLAS / 旅行足迹</div><h1>循着地图，慢慢走。</h1><p>沿着真实的山海轮廓，记录中国与日本的旅行足迹。点击省份或都道府县阅读游记，放大地图，看看下一站想去哪里。</p></div>${atlasSection(true)}<section class="directory"><div class="section-heading"><h3>从地名，找到一段记忆。</h3><div class="search-field"><input id="region-search" type="search" placeholder="搜索省份或都道府县…" aria-label="搜索地区"></div></div><div id="directory-results">${directory()}</div></section>`;}
function directory(){const found=regions.filter(r=>(r.full+countryName(r.country)).includes(mapSearch));return ['cn','jp'].map(c=>{const items=found.filter(r=>r.country===c);return items.length?`<p class="tiny-label" style="margin-top:22px">${countryName(c)} / ${items.length} 个地区</p><div class="region-directory">${items.map(r=>`<a class="region-chip" href="#/region/${r.id}"><i class="swatch" style="background:${colorFor(r.id)}"></i>${r.name}<small>${regionPosts(state,r.id).length||'·'}</small></a>`).join('')}</div>`:'';}).join('')||'<div class="empty-state"><h3>没有找到这个地区</h3><p>可以试试“浙江”“东京”或“北海道”。</p></div>';}
function regionPage(id){const r=regionById(id);if(!r)return notFound();const posts=regionPosts(state,id);return `<div class="page-head"><div class="breadcrumb"><a href="#/atlas">旅行地图</a> / ${countryName(r.country)} / ${r.name}</div><div class="region-hero"><div><div class="eyebrow">${r.country.toUpperCase()} / A PIECE OF MY JOURNEY</div><div class="region-title-line"><h1>${r.name}</h1>${statusPill(id)}</div><p>${r.full} · ${posts.length} 篇旅行手记<br>${posts.length?'地图上的一块颜色，生活里的一段记忆。':'这里的故事还在路上，先为下一次出发留一页空白。'}</p><div class="region-actions"><button class="button" data-action="new-region-post" data-id="${id}">写一篇这里的游记 ↗</button><button class="button secondary" data-action="edit-status" data-id="${id}">编辑足迹与颜色</button></div></div><div class="mini-map"><svg viewBox="${r.bounds.join(' ')}" aria-hidden="true">${regionSVG(r,true)}</svg></div></div></div><div class="section-heading"><h2>关于${r.name}的手记</h2><span class="right-note">${posts.length} 篇记录</span></div>${posts.length?`<div class="post-grid section-spacer">${posts.map(postCard).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">山</div><h3>故事，从这一页开始。</h3><p>还没有关于${r.name}的文章。记一段路、一个人，或一顿难忘的晚餐。</p><button class="button secondary" data-action="new-region-post" data-id="${id}">写下第一篇游记 ↗</button></div>`}`;}
function articlePage(id,preview=false){const p=preview&&session?(draftFor(id)||state.posts.find(p=>p.id===id)):state.posts.find(p=>p.id===id&&p.status==='published');if(!p)return notFound();return `<article class="article"><div class="breadcrumb muted" style="font-size:11px"><a href="${p.regions.length?'#/region/'+p.regions[0]:'#/essays'}">← ${p.regions.length?regionById(p.regions[0])?.name+'的游记':'所有随笔'}</a></div>${p.status==='draft'?'<div class="notice" style="margin-top:20px">本机草稿预览 · 尚未提交 GitHub</div>':''}<div class="post-meta" style="margin-top:25px"><span class="category">${p.type==='travel'?'旅行手记':'日常随笔'}</span><span>·</span><time>${esc(p.date)}</time>${p.regions.map(id=>`<a href="#/region/${esc(id)}">${esc(regionById(id)?.name||'')}</a>`).join('')}</div><h1>${esc(p.title)}</h1><p class="muted" style="font-size:13px">${esc(p.excerpt)}</p><img class="article-cover" src="${esc(safeImage(p.cover))}" alt="${esc(p.title)}封面"><div class="article-body">${renderBody(p.body)}</div><div class="article-bottom"><a href="#/essays">← 返回文章列表</a><a href="#/admin/edit/${encodeURIComponent(p.id)}">编辑这篇文章 ↗</a></div></article>`;}
function essayResults(){const posts=publishedPosts(state).filter(p=>(essayFilter==='all'||p.type===essayFilter)&&(p.title+p.excerpt).toLowerCase().includes(listSearch.toLowerCase()));return posts.length?`<div class="post-grid">${posts.map(postCard).join('')}</div>`:'<div class="empty-state"><h3>还没有找到这篇文章</h3><p>换一个关键词，或去后台写下新的故事。</p></div>';}
function essays(){return `<div class="page-head"><div class="eyebrow">NOTES ON LIFE & EVERYTHING ELSE</div><h1>把日子，写成一些文字。</h1><p>旅途中的片刻、研究之外的思考，以及那些不想轻易忘记的小事。</p></div><div class="filter-tabs">${[['all','全部文章'],['essay','日常随笔'],['travel','旅行手记']].map(([v,t])=>`<button data-action="filter-essay" data-value="${v}" class="${essayFilter===v?'active':''}">${t}</button>`).join('')}<div class="search-field"><input id="post-search" type="search" value="${esc(listSearch)}" aria-label="搜索文章" placeholder="搜索文章…"></div></div><div id="essay-results" class="section-spacer">${essayResults()}</div>`;}
function academic(){return `<div class="page-head"><div class="eyebrow">RESEARCH & CURIOSITY</div><h1>学术，也是探索世界的方式。</h1><p>这里承载你的研究、论文与经历。以下为可替换的资料占位，不代表实际学术履历。</p></div><div class="profile-layout"><aside class="profile-sidebar"><div class="avatar">名</div><h2>你的名字</h2><p>Your Name · 个人学术主页<br>院系 / 学校 / 研究机构</p><div class="profile-links"><a href="https://scholar.google.com/" target="_blank" rel="noopener noreferrer">Scholar ↗</a><a href="https://github.com/" target="_blank" rel="noopener noreferrer">GitHub ↗</a><a href="https://orcid.org/" target="_blank" rel="noopener noreferrer">ORCID ↗</a></div><p style="margin-top:14px;font-size:9px">以上为平台入口，正式版替换为个人链接</p></aside><div><section class="profile-section"><h2>关于我 <span class="muted" style="font:10px var(--sans);margin-left:10px">ABOUT</span></h2><p>在这里用几句话介绍自己：正在研究的问题、求学经历，以及是什么让你保持好奇。可以放中英文双语简介，让来自不同地方的读者认识你。</p><div class="research-tags"><span>研究方向一（待填写）</span><span>研究方向二（待填写）</span><span>研究方向三（待填写）</span></div></section><section class="profile-section"><h2>最近动态 <span class="muted" style="font:10px var(--sans);margin-left:10px">NEWS</span></h2><div class="placeholder-card"><strong>等待你的第一条学术动态</strong>论文录用、会议报告、项目进展，都可以在正式版后台按日期发布。</div></section><section class="profile-section"><h2>代表论文 <span class="muted" style="font:10px var(--sans);margin-left:10px">SELECTED PUBLICATIONS</span></h2><div class="placeholder-card"><strong>论文标题 / Publication title</strong>作者列表 · 期刊或会议 · 年份<br>预留 Paper、Code、Project 与 BibTeX 链接字段。</div></section><section class="profile-section"><h2>教育与经历 <span class="muted" style="font:10px var(--sans);margin-left:10px">EXPERIENCE</span></h2><p>年份 — 年份 &nbsp; 学位 / 职位 · 机构（待填写）<br>在正式版中，通过后台新增条目并调整展示顺序。</p></section><a class="text-link" href="#/plan">查看资料后台的实现方案 ↗</a></div></div>`;}
function links(){const cards=[['学','Google Scholar','寻找论文，也寻找下一次灵感。','https://scholar.google.com/'],['码','GitHub','代码、项目与开放的想法。','https://github.com/'],['读','arXiv','新问题与新知识的起点。','https://arxiv.org/'],['记','你的朋友的博客','为朋友的文字留一个位置。',null],['窗','常读的网站','收藏一个值得反复打开的页面。',null],['远','下一个好去处','网络世界里的路，也可以慢慢走。',null]];return `<div class="page-head"><div class="eyebrow">A SMALL CORNER OF THE INTERNET</div><h1>一些，值得停留的地方。</h1><p>收藏常用的学术入口，也给朋友的博客留一扇窗。下面的友链为示例位置，正式版可在后台添加、排序或隐藏。</p></div><div class="friend-grid">${cards.map(([icon,title,description,url])=>`${url?`<a href="${url}" target="_blank" rel="noopener noreferrer"`:'<div'} class="friend-card"><span class="friend-icon">${icon}</span><div><h3>${title}</h3><p>${description}</p><span class="external">${url?new URL(url).hostname+' ↗':'待添加链接 · 占位'}</span></div>${url?'</a>':'</div>'}`).join('')}</div><div class="plan-banner"><p class="muted" style="font-size:12px">友链字段：站点名称、网址、简介、图标、分组与排序。正式上线后，全部在可视化后台维护。</p><a class="text-link" href="#/plan">查看完整实现方案 ↗</a></div>`;}

function login(){return `<section class="login-card github-login"><div class="brand-mark">山</div><div class="eyebrow">YOUR WRITING ROOM / GITHUB</div><h1>连接你的博客仓库。</h1><p>文章、照片与足迹直接保存到<br><a href="${GITHUB.url}" target="_blank" rel="noopener noreferrer"><strong>${GITHUB.owner}/${GITHUB.repo}</strong> ↗</a></p><form id="github-login"><label class="field" style="text-align:left"><span>GitHub 细粒度访问令牌</span><input name="token" type="password" autocomplete="off" placeholder="github_pat_…" required aria-label="GitHub 访问令牌"></label><label class="remember-token"><input type="checkbox" name="remember"> 在当前标签页会话中记住授权，退出时清除</label><button class="button" type="submit">连接 GitHub，进入写作后台 ↗</button><p id="login-error" class="form-error" role="alert"></p></form><details class="token-help"><summary>第一次使用：如何获得令牌？</summary><ol><li>打开 <a href="https://github.com/settings/personal-access-tokens/new?name=fieldnotes-blog&amp;target_name=weijungao575-hash&amp;contents=write" target="_blank" rel="noopener noreferrer">GitHub 令牌创建页面 ↗</a>。</li><li>Resource owner 选 <strong>weijungao575-hash</strong>。</li><li>Repository access 选 <strong>Only select repositories</strong>，只勾选 <strong>fieldnotes-blog</strong>。</li><li>Repository permissions 中，将 <strong>Contents</strong> 设为 <strong>Read and write</strong>。其余保持默认。</li><li>由你本人生成令牌，复制到上方输入框，再点击连接。</li></ol><p>令牌只发送到 GitHub API，不写入文章、照片或仓库。无需把令牌发给任何人。有效期结束后需重新生成。</p></details><p class="login-foot">无需租服务器 · 草稿留本机，发布才上传</p></section>`;}
function adminLayout(content,page='posts'){return `<section class="admin-shell"><aside class="admin-sidebar"><div class="admin-brand">写作间</div><a class="${page==='posts'?'active':''}" href="#/admin">▤ &nbsp; 文章管理</a><a class="${page==='new'?'active':''}" href="#/admin/new">＋ &nbsp; 写新文章</a><a class="${page==='maps'?'active':''}" href="#/admin/maps">◇ &nbsp; 足迹与着色</a><a class="${page==='backup'?'active':''}" href="#/admin/backup">↓ &nbsp; 数据备份</a><a href="#/">↗ &nbsp; 查看博客</a><div class="admin-bottom">GitHub · ${esc(account)}<br><button data-action="logout" style="padding:4px 0;font-size:10px">断开连接 ↗</button></div></aside><div class="admin-main">${content}</div></section>`;}
function adminHome(){const posts=editingPosts(state,drafts);return adminLayout(`<div class="admin-heading"><div><h1>你的文字，都在这里。</h1><p>已发布内容来自 GitHub 仓库，本机草稿只对你可见。</p></div><a href="#/admin/new" class="button small">＋ 写新文章</a></div><div class="notice success-notice">已连接 ${esc(account)} · 点击发布会将文章和照片提交到 GitHub，Pages 随后自动更新。<button class="text-link" data-action="refresh-repository">重新加载仓库 ↻</button></div><div class="stats-grid"><div class="stat-box"><span>仓库中的文章</span><strong>${state.posts.length}</strong></div><div class="stat-box"><span>本机草稿</span><strong>${drafts.length}</strong></div><div class="stat-box"><span>已到访地区</span><strong>${visitStats(state).been}</strong></div></div><div class="table-wrap"><table class="admin-table"><thead><tr><th>文章标题</th><th>分类 / 地区</th><th>状态</th><th>操作</th></tr></thead><tbody>${posts.map(p=>`<tr><td><a href="#/admin/edit/${encodeURIComponent(p.id)}">${esc(p.title)}</a><br><small class="muted">${esc(p.date)}</small></td><td>${p.type==='travel'?'旅行':'随笔'}${p.regions.length?' · '+p.regions.map(id=>esc(regionById(id)?.name||'')).join(' / '):''}</td><td><span class="status-pill">${p.status==='draft'?'本机草稿':'已提交 GitHub'}</span></td><td><a href="#/admin/edit/${encodeURIComponent(p.id)}">编辑 ↗</a></td></tr>`).join('')}</tbody></table></div>`);}
function editorPage(id,regionId){const post=id?postForEdit(id):null;if(id&&!post)return notFound();editorBasePost=post&&Object.hasOwn(post,'basePublic')?structuredClone(post.basePublic):structuredClone(state.posts.find(p=>p.id===id)||null);editorAttachments=(post?.body||[]).filter(b=>b.type==='image').map(b=>({...b}));const selected=post?.regions||[regionId].filter(Boolean);return adminLayout(`<div class="admin-heading"><div><h1>${post?'编辑这篇记忆。':'写下，一段新的故事。'}</h1><p>文章可关联一个或多个地区，发布后会出现在对应地区页面。</p></div><div><a class="text-link" href="#/admin">返回文章列表</a>${id&&state.posts.some(p=>p.id===id)?'<button type="button" class="text-link" data-action="load-repository-version" style="display:block;margin-top:7px;font-size:10px">载入仓库最新正文 ↻</button>':''}</div></div><form id="post-form" data-id="${esc(id||'')}" data-operation-id="${esc(post?.pendingOperationId||'')}"><div class="form-grid"><div><label class="field"><span>文章标题 *</span><input class="title-input" name="title" maxlength="140" placeholder="给这段记忆起个名字…" value="${esc(post?.title||'')}" required></label><label class="field"><span>摘要</span><textarea name="excerpt" maxlength="300" placeholder="用一两句话，留住这篇文章的开头。">${esc(post?.excerpt||'')}</textarea></label><label class="field"><span>正文 *</span></label><div class="editor-frame"><div class="editor-toolbar" aria-label="文字格式"><button type="button" data-command="bold" title="加粗"><b>B</b></button><button type="button" data-command="italic" title="斜体"><i>I</i></button><button type="button" data-command="formatBlock" data-argument="h2" title="二级标题">H2</button><button type="button" data-command="formatBlock" data-argument="p">正文</button><button type="button" data-command="formatBlock" data-argument="blockquote">引用</button><button type="button" data-action="add-link">超链接 ↗</button></div><div class="rich-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="文章正文" id="rich-editor">${post?renderBody(post.body.filter(b=>b.type!=='image')):''}</div></div></div><aside class="editor-side"><h3>文章设置</h3><label class="field"><span>文章类型</span><select name="type"><option value="travel" ${post?.type==='essay'?'':'selected'}>旅行手记</option><option value="essay" ${post?.type==='essay'?'selected':''}>日常随笔</option></select></label><label class="field"><span>日期</span><input type="date" name="date" value="${esc(post?.date||new Date().toLocaleDateString('sv-SE'))}" required></label><div class="field travel-region-field"><span>关联地区（旅行手记必选）</span><input class="region-picker-search" id="picker-search" placeholder="搜索地区…" aria-label="筛选关联地区"><div class="region-picker">${regions.map(r=>`<label data-picker-name="${r.full}"><input type="checkbox" name="regions" value="${r.id}" ${selected.includes(r.id)?'checked':''}>${countryName(r.country)} · ${r.full}</label>`).join('')}</div><div class="selected-regions" id="selected-regions">已选择 ${selected.length} 个地区</div></div><div class="field photos-field"><span>上传照片</span><label class="upload-zone"><span>＋</span>选择照片，附在正文之后<input type="file" id="photo-upload" accept="image/jpeg,image/png,image/webp" multiple aria-label="上传文章照片"></label><p class="muted" style="font-size:9px;margin-top:6px">最多 8 张，每张 ≤ 8 MB；发布时压缩并上传 GitHub，首张作为封面。</p><div class="attachments" id="attachments">${attachmentsHTML()}</div></div></aside></div><div class="editor-footer"><small id="save-hint">${post?'已加载文章 · 草稿保存在本机':'尚未保存 · 离开前请保存草稿'}</small><div><button class="button secondary" type="submit" name="intent" value="draft">保存本机草稿</button><button class="button" type="submit" name="intent" value="published">${state.posts.some(p=>p.id===post?.id)?'更新到 GitHub':'发布到 GitHub'} ↗</button></div></div></form>`,'new');}
function attachmentsHTML(){return editorAttachments.map((a,i)=>`<div class="attachment"><img src="${esc(safeImage(a.src))}" alt="${esc(a.alt||'待上传照片')}"><button type="button" data-action="remove-photo" data-index="${i}" aria-label="移除第 ${i+1} 张照片">×</button></div>`).join('');}
function adminMaps(){return adminLayout(`<div class="admin-heading"><div><h1>给足迹，一点颜色。</h1><p>调整后点击保存，足迹状态和独立颜色会写入 GitHub。</p></div><button class="button small" data-action="save-map">保存足迹到 GitHub ↗</button></div><div class="notice">状态用于到访统计；色块可自定义。“默认”恢复状态配色。<span id="map-save-hint">${mapEdits.size?'有 '+mapEdits.size+' 个地区待保存':'所有足迹已与仓库同步'}</span></div><div class="search-field" style="margin-bottom:18px"><input id="admin-region-search" type="search" placeholder="搜索地区…" aria-label="搜索要编辑的地区"></div><div class="map-admin-list">${regions.map(r=>`<div class="map-admin-row" data-region-row="${r.full}"><a class="region-name" href="#/region/${r.id}">${r.name}</a><small class="muted">${r.country.toUpperCase()}</small><select class="status-select" data-status-id="${r.id}" aria-label="${r.name}足迹状态">${Object.entries(STATUS).map(([key,s])=>`<option value="${key}" ${(state.visits[r.id]||'none')===key?'selected':''}>${s.label}</option>`).join('')}</select><input class="color-input" type="color" value="${colorFor(r.id)}" data-color-id="${r.id}" aria-label="${r.name}自定义颜色"><button class="reset-color" data-action="reset-color" data-id="${r.id}">默认</button></div>`).join('')}</div>`,'maps');}
function backupPage(){return adminLayout(`<div class="admin-heading"><div><h1>给记忆，留一份备份。</h1><p>GitHub 保存已发布内容；导出文件还会包含本机草稿。</p></div></div><div class="notice">文章和照片的每次发布都有 GitHub 提交记录。本机草稿不会上传；可导出 JSON 备份以便换设备或迁移。</div><div class="backup-actions"><button class="button" data-action="export">导出完整备份 ↓</button><label class="button secondary" style="cursor:pointer">导入文章为本机草稿 ↑<input type="file" id="import-backup" accept="application/json,.json" hidden></label><button class="button secondary" data-action="import-legacy">读取旧版浏览器文章</button></div><p class="muted" style="font-size:12px;line-height:2">仓库中有 ${state.posts.length} 篇文章，本机有 ${drafts.length} 篇草稿。<br>导入仅新增或更新本机草稿，不覆盖仓库中的文章或足迹。逐篇确认后可在编辑器中发布。</p><div class="placeholder-card" style="margin-top:30px"><strong>直接查看 GitHub 中的数据</strong><a class="text-link" href="${GITHUB.url}/blob/main/content.json" target="_blank" rel="noopener noreferrer">文章与足迹：content.json ↗</a><br><a class="text-link" href="${GITHUB.url}" target="_blank" rel="noopener noreferrer">照片发布后会出现在 uploads/ 目录 ↗</a></div>`,'backup');}

function planPage(){return `<div class="page-head"><div class="eyebrow">YOUR BLOG, YOUR GITHUB REPOSITORY</div><h1>文字与足迹，都有归处。</h1><p>这个博客使用 GitHub 保存文章、照片和地图状态，通过 GitHub Pages 展示。无需租用服务器或配置数据库。</p></div><div class="plan-content"><div class="plan-banner"><p><strong>浏览器写作 → 提交 GitHub → Pages 自动更新。</strong><br>普通访客读取公开内容；只有持有仓库写入授权的人才能发布。</p></div><h2>内容放在哪里</h2><table class="plan-table"><thead><tr><th>内容</th><th>GitHub 中的位置</th></tr></thead><tbody><tr><td>已发布文章与地区关联</td><td>content.json / posts</td></tr><tr><td>81 个地区的状态与颜色</td><td>content.json / visits、colors</td></tr><tr><td>旅行照片</td><td>uploads/，以照片内容生成唯一文件名</td></tr><tr><td>本机草稿</td><td>当前浏览器；不会上传到公开仓库</td></tr><tr><td>网站页面与编辑器</td><td>index.html，通过 Pages 托管</td></tr></tbody></table><h2>第一次开始写作</h2><ol class="plan-list"><li>打开写作后台，按页面说明创建仅可访问此仓库的 GitHub 细粒度令牌。</li><li>由你本人将令牌输入后台，点击连接。</li><li>写正文、选择地区、上传照片；可先保存本机草稿。</li><li>点击“发布到 GitHub”，文章和照片在同一笔提交中保存。</li><li>等待 Pages 自动部署，使用“检查网站更新”确认访客可读取新版本。</li></ol><h2>保存时会发生什么</h2><p>后台会先读取仓库最新内容，再合并当前文章或足迹修改。它保留其他文章和网站文件；如果同一篇文章或地区已在其他设备修改，会提示冲突，不强制覆盖。照片和文章一起提交，上传失败不会留下半篇公开文章。</p><h2>关于照片和公开内容</h2><p>照片会自动压缩，发布后作为文件保存在 GitHub。当前仓库公开，因此发布的文章、照片和足迹都公开可见。草稿留在本机；导出的备份文件可用来迁移草稿。学术主页的示例资料和友链位置仍可通过仓库源文件替换。</p><h2>发布进度</h2><p>“提交成功”表示内容已存进 GitHub；Pages 还需要完成一次部署。后台会显示提交链接，并提供“检查网站更新”。未连接授权的访客也能阅读公开文章，但无法写入仓库。</p><a class="button" href="#/admin" style="margin-top:25px">进入写作后台 ↗</a><a class="text-link" href="${GITHUB.url}" target="_blank" rel="noopener noreferrer" style="margin-left:20px">查看博客仓库 ↗</a></div>`;}
function notFound(){return '<div class="empty-state" style="margin-top:50px"><h3>这一页，还没有写下故事。</h3><p>文章可能尚未发布，或链接已发生变化。</p><a class="button" href="#/">回到首页</a></div>';}
let currentRoute='';
function render(){tooltip.hidden=true;const raw=location.hash.slice(1)||'/';const [path,query='']=raw.split('?');const parts=path.split('/').filter(Boolean).map(s=>{try{return decodeURIComponent(s);}catch{return s;}});const page=parts[0]||'home';
 if(saving&&currentRoute!==raw){history.replaceState(null,'','#'+currentRoute);toast('正在保存到 GitHub，请稍候');return;}
 if((editorDirty||mapEdits.size)&&currentRoute!==raw){dialog.innerHTML='<h2>还有未保存的修改。</h2><p>可以继续编辑并保存，或放弃本页的未保存修改。</p><div class="dialog-actions"><button class="button secondary" data-action="leave-editor" data-target="'+esc(raw)+'">放弃修改并离开</button><button class="button" data-action="stay-editor">继续编辑</button></div>';history.replaceState(null,'','#'+currentRoute);dialog.showModal();return;}
 currentRoute=raw;const params=new URLSearchParams(query);let html,title='山海之间';
 if(page==='home'){html=home();title='山海之间 · 学术、旅行与日常';}
 else if(page==='atlas'){html=atlasPage();title='旅行地图 · 山海之间';}
 else if(page==='region'){html=regionPage(parts[1]);title=(regionById(parts[1])?.name||'地区')+' · 山海之间';}
 else if(page==='post'){html=articlePage(parts[1]);title=(state.posts.find(p=>p.id===parts[1])?.title||'文章')+' · 山海之间';}
 else if(page==='preview'){html=articlePage(parts[1],true);title='草稿预览 · 山海之间';}
 else if(page==='academic'){html=academic();title='学术主页 · 山海之间';}
 else if(page==='essays'){html=essays();title='随笔 · 山海之间';}
 else if(page==='links'){html=links();title='友情链接 · 山海之间';}
 else if(page==='plan'){html=planPage();title='实现方案 · 山海之间';}
 else if(page==='admin'){title='写作后台 · 山海之间';if(!session)html=login();else if(parts[1]==='new')html=editorPage(null,params.get('region'));else if(parts[1]==='edit')html=editorPage(parts[2]);else if(parts[1]==='maps')html=adminMaps();else if(parts[1]==='backup')html=backupPage();else html=adminHome();}
 else html=notFound();
 main.innerHTML=(session&&lastCommit?publicationReceipt():'')+html;document.title=title;document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===page||(page==='region'&&a.dataset.nav==='atlas')||(page==='post'&&a.dataset.nav==='essays');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelector('nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');window.scrollTo(0,0);}

function showStatusDialog(id){const r=regionById(id);dialog.innerHTML=`<h2>为${r.name}留下一块颜色。</h2><p>状态用于足迹统计；也可以单独自定义颜色。</p><form id="status-form" data-id="${id}"><div class="status-options">${Object.entries(STATUS).map(([key,s])=>`<label><input type="radio" name="status" value="${key}" ${(state.visits[id]||'none')===key?'checked':''}><i class="swatch" style="background:${s.color}"></i>${s.label}</label>`).join('')}</div><label class="field" style="margin-top:20px"><span>自定义颜色（可选）</span><input name="color" type="color" value="${colorFor(id)}" style="height:40px"></label><label style="font-size:11px;color:#8a9b78"><input type="checkbox" name="custom" ${state.colors[id]?'checked':''}> 使用自定义颜色</label><div class="dialog-actions"><button type="button" class="button secondary" data-action="close-dialog">取消</button><button class="button" type="submit">保存到 GitHub</button></div></form>`;dialog.showModal();}
function ensureSession(target){if(session){go(target);return;}try{sessionStorage.setItem('fieldnotes-return',target);}catch{}go('/admin');toast('先连接 GitHub，再写作或编辑足迹');}

function publicationReceipt(){return `<div id="publication-receipt" class="publish-receipt" role="status"><div><strong>${lastCommit.live?'网站已更新，访客可以看到最新内容。':'已成功保存到 GitHub，正在等待 Pages 更新。'}</strong><span>${lastCommit.live?'保存完成。':'你当前看到的是已提交版本；其他访客在部署完成后刷新即可看到。'}</span></div><div><a href="${GITHUB.url}/commit/${lastCommit.sha}" target="_blank" rel="noopener noreferrer">查看提交 ↗</a><button data-action="check-live">检查网站更新 ↻</button></div></div>`;}
function setBusy(value){saving=value;document.querySelectorAll('#post-form button,#post-form input,#post-form textarea,#post-form select,#github-login button,#github-login input,.map-admin-list input,.map-admin-list select,[data-action="save-map"],#status-form button,#status-form input').forEach(el=>el.disabled=value);const rich=document.querySelector('#rich-editor');if(rich)rich.contentEditable=value?'false':'true';}
function trackMap(id){const actual=mapValue(state,id),base=mapValue(repositoryState,id);if(canonical(actual)===canonical(base))mapEdits.delete(id);else mapEdits.set(id,{id,...actual,expected:base});const hint=document.querySelector('#map-save-hint');if(hint)hint.textContent=mapEdits.size?`有 ${mapEdits.size} 个地区待保存`:'所有足迹已与仓库同步';}
async function readPublicContent(){if(location.protocol==='file:'&&globalThis.FIELDNOTES_INITIAL_CONTENT)return validateContent(globalThis.FIELDNOTES_INITIAL_CONTENT);const response=await fetch('content.json?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!response.ok)throw new Error('无法读取网站内容，请稍后重试');return validateContent(await response.json());}
async function connectRepository(token,remember=false){const client=new GitHubRepository(token);try{const result=await client.connect();adoptSite(result.snapshot.site);repository=client;account=result.login;session=true;try{if(remember)sessionStorage.setItem(SESSION_TOKEN_KEY,token);else sessionStorage.removeItem(SESSION_TOKEN_KEY);}catch{}return result;}catch(error){client.disconnect();throw error;}}
async function refreshRepository(){if(editorDirty||mapEdits.size){toast('请先保存当前修改');return;}setBusy(true);try{const result=await repository.read();adoptSite(result.site);render();toast('已读取仓库最新内容，本机草稿保持不变');}catch(error){toast(error.message);}finally{setBusy(false);}}
async function saveMapChanges(changes){if(!session||!repository){ensureSession('/admin/maps');return;}setBusy(true);try{const fingerprint=canonical(changes);if(pendingMapOperation?.fingerprint!==fingerprint)pendingMapOperation={fingerprint,id:crypto.randomUUID()};const result=await repository.saveMap(changes,{operationId:pendingMapOperation.id});pendingMapOperation=null;adoptSite(result.site);mapEdits.clear();lastCommit={sha:result.sha,revision:result.site.mapRevision,kind:'map',live:false};dialog.close();render();toast('足迹已提交 GitHub，Pages 将自动更新');}catch(error){toast(error.message);}finally{setBusy(false);}}

async function loadRepositoryVersion(){const form=document.querySelector('#post-form');if(!form||!repository)return;const data=new FormData(form),existing=postForEdit(form.dataset.id);const backup={id:'recovery-'+crypto.randomUUID(),title:(String(data.get('title')).trim()||'未命名文章').slice(0,125)+'（本机备份）',excerpt:String(data.get('excerpt')||''),type:data.get('type'),regions:data.get('type')==='travel'?data.getAll('regions'):[],date:data.get('date'),cover:editorAttachments[0]?.src||existing?.cover||'assets/desk.svg',body:[...extractEditor(),...editorAttachments],status:'draft',basePublic:null};setBusy(true);try{const result=await repository.read();const before=structuredClone(drafts);drafts=drafts.filter(p=>p.id!==form.dataset.id);drafts.push(backup);if(!persistDrafts()){drafts=before;return;}adoptSite(result.site);editorDirty=false;render();toast('已载入仓库正文，原编辑内容另存为本机备份草稿');}catch(error){toast(error.message);}finally{setBusy(false);}}

async function checkLive(){if(!lastCommit)return;const button=document.querySelector('[data-action="check-live"]');if(button)button.disabled=true;try{const site=await readPublicContent();const applied=lastCommit.kind==='post'?site.posts.some(p=>p.id===lastCommit.id&&p.version===lastCommit.revision):site.mapRevision===lastCommit.revision;if(applied){lastCommit.live=true;const receipt=document.querySelector('#publication-receipt');if(receipt)receipt.outerHTML=publicationReceipt();toast('网站已更新，访客可看到最新内容');}else toast('内容已在 GitHub 保存，Pages 仍在部署，请稍后再检查');}catch{toast('暂时无法检查网站更新，请稍后重试');}finally{const b=document.querySelector('[data-action="check-live"]');if(b)b.disabled=false;}}
function downloadableBackup(){return {version:2,exportedAt:new Date().toISOString(),content:structuredClone(repositoryState),drafts:structuredClone(drafts)};}
function offerImport(posts){const entries=new Map();for(const post of posts){const copy=structuredClone(post);delete copy.basePublic;copy.status='published';entries.set(copy.id,copy);}validateContent({formatVersion:2,posts:[...entries.values()],visits:{},colors:{}});dialog.innerHTML=`<h2>导入 ${entries.size} 篇文章为本机草稿？</h2><p>不会修改仓库或公开网站。同 ID 的本机草稿会被此备份替换。之后可逐篇检查并发布到 GitHub。</p><div class="dialog-actions"><button class="button secondary" data-action="close-dialog">取消</button><button class="button" id="confirm-import">导入本机草稿</button></div>`;dialog.querySelector('#confirm-import').onclick=()=>{const before=structuredClone(drafts);for(const post of entries.values()){post.status='draft';post.basePublic=structuredClone(state.posts.find(p=>p.id===post.id)||null);const index=drafts.findIndex(p=>p.id===post.id);if(index<0)drafts.push(post);else drafts[index]=post;}if(persistDrafts()){dialog.close();render();toast('已导入本机草稿，尚未公开发布');}else drafts=before;};dialog.showModal();}

document.querySelector('.menu-toggle').addEventListener('click',e=>{const open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);});
document.addEventListener('click',async e=>{
  if(suppressMapClick&&e.target.closest('.map-canvas')){suppressMapClick=false;e.preventDefault();return;}
  if(e.target.closest('.skip-link')){e.preventDefault();main.focus();return;}
  if(saving&&e.target.closest('a,[data-action],[data-region]')){e.preventDefault();toast('正在保存到 GitHub，请稍候');return;}
  const region=e.target.closest('[data-region]');if(region&&!region.closest('.mini-map')){go('/region/'+region.dataset.region);return;}
  const command=e.target.closest('[data-command]');if(command){e.preventDefault();document.execCommand(command.dataset.command,false,command.dataset.argument||null);document.querySelector('#rich-editor').focus();delete document.querySelector('#post-form').dataset.operationId;editorDirty=true;return;}
  const b=e.target.closest('[data-action]');if(!b)return;const {action,id,value}=b.dataset;
  if(action==='map-zoom'||action==='map-reset'){const country=b.dataset.country,camera=mapCameras[country],[,,w,h]=MAP_VIEWBOX[country].split(' ').map(Number);if(action==='map-reset')Object.assign(camera,{x:w/2,y:h/2,zoom:1});else camera.zoom=Math.max(1,Math.min(5,camera.zoom*Number(b.dataset.factor)));camera.x=Math.max(w/camera.zoom/2,Math.min(w-w/camera.zoom/2,camera.x));camera.y=Math.max(h/camera.zoom/2,Math.min(h-h/camera.zoom/2,camera.y));document.querySelector(`[data-map-country="${country}"]`).setAttribute('viewBox',mapViewBox(country));}
  else if(action==='filter-map'){mapFilter=value;const y=window.scrollY;main.querySelector('.atlas-section').outerHTML=atlasSection(location.hash.startsWith('#/atlas'));window.scrollTo(0,y);}
  else if(action==='filter-essay'){essayFilter=value;main.querySelectorAll('[data-action="filter-essay"]').forEach(el=>el.classList.toggle('active',el.dataset.value===value));document.querySelector('#essay-results').innerHTML=essayResults();}
  else if(action==='logout'){if(editorDirty||mapEdits.size){toast('请先保存或放弃当前修改，再断开连接');return;}repository?.disconnect();repository=null;session=false;account='';lastCommit=null;try{sessionStorage.removeItem(SESSION_TOKEN_KEY);}catch{}go('/admin');render();toast('已断开 GitHub，当前会话中的令牌已清除');}
  else if(action==='new-region-post')ensureSession('/admin/new?region='+id);
  else if(action==='edit-status'){if(session)showStatusDialog(id);else ensureSession('/admin/maps');}
  else if(action==='reset-color'){delete state.colors[id];document.querySelector(`[data-color-id="${id}"]`).value=colorFor(id);trackMap(id);}
  else if(action==='save-map'){if(!mapEdits.size)toast('没有需要保存的修改');else await saveMapChanges([...mapEdits.values()]);}
  else if(action==='check-live')await checkLive();
  else if(action==='refresh-repository')await refreshRepository();
  else if(action==='load-repository-version')await loadRepositoryVersion();
  else if(action==='close-dialog')dialog.close();
  else if(action==='remove-photo'){delete document.querySelector('#post-form').dataset.operationId;editorAttachments.splice(Number(b.dataset.index),1);document.querySelector('#attachments').innerHTML=attachmentsHTML();editorDirty=true;}
  else if(action==='export'){const blob=new Blob([JSON.stringify(downloadableBackup(),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='fieldnotes-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出，不包含 GitHub 令牌');}
  else if(action==='import-legacy'){try{const old=loadState();const changed=old.posts.filter(p=>canonical(p)!==canonical(state.posts.find(v=>v.id===p.id)));if(changed.length)offerImport(changed);else toast('旧版浏览器中没有需要迁移的文章');}catch{toast('无法读取旧版数据，请导出 JSON 后导入');}}
  else if(action==='add-link'){const input=prompt('请输入完整链接（https://…）');if(input){const url=safeURL(input);if(url){document.execCommand('createLink',false,url);delete document.querySelector('#post-form').dataset.operationId;editorDirty=true;}else toast('请输入有效的 http、https 或邮件链接');}}
  else if(action==='leave-editor'){editorDirty=false;mapEdits.clear();state=structuredClone(repositoryState);dialog.close();go(b.dataset.target);}
  else if(action==='stay-editor')dialog.close();
  else if(action==='retry-load')await boot();
});
document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-command], [data-action="add-link"]'))e.preventDefault();});
document.addEventListener('pointerdown',e=>{const svg=e.target.closest('svg[data-map-country]');if(!svg||e.button!==0||mapCameras[svg.dataset.mapCountry].zoom<=1)return;const country=svg.dataset.mapCountry,rect=svg.getBoundingClientRect(),camera=mapCameras[country],[,,w,h]=svg.getAttribute('viewBox').split(' ').map(Number);mapDrag={svg,country,clientX:e.clientX,clientY:e.clientY,x:camera.x,y:camera.y,scaleX:w/rect.width,scaleY:h/rect.height,moved:false};svg.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!mapDrag)return;const d=mapDrag,dx=e.clientX-d.clientX,dy=e.clientY-d.clientY;if(!d.moved&&Math.hypot(dx,dy)<5)return;d.moved=true;tooltip.hidden=true;d.svg.classList.add('is-dragging');const camera=mapCameras[d.country],[,,w,h]=MAP_VIEWBOX[d.country].split(' ').map(Number);camera.x=Math.max(w/camera.zoom/2,Math.min(w-w/camera.zoom/2,d.x-dx*d.scaleX));camera.y=Math.max(h/camera.zoom/2,Math.min(h-h/camera.zoom/2,d.y-dy*d.scaleY));d.svg.setAttribute('viewBox',mapViewBox(d.country));});
document.addEventListener('pointerup',e=>{if(!mapDrag)return;const d=mapDrag;if(d.svg.hasPointerCapture(e.pointerId))d.svg.releasePointerCapture(e.pointerId);d.svg.classList.remove('is-dragging');suppressMapClick=d.moved;mapDrag=null;});
document.addEventListener('pointercancel',()=>{if(mapDrag)mapDrag.svg.classList.remove('is-dragging');mapDrag=null;suppressMapClick=false;});
document.addEventListener('keydown',e=>{const r=e.target.closest('[data-region]');if(r&&(e.key==='Enter'||e.key===' ')){e.preventDefault();go('/region/'+r.dataset.region);}});
function displayTooltip(el,x,y){const r=regionById(el.dataset.region);tooltip.innerHTML=`<strong>${r.full}</strong><small>${statusFor(r.id).label} · ${regionPosts(state,r.id).length} 篇游记 · 点击进入 ↗</small>`;tooltip.hidden=false;tooltip.style.left=Math.min(x+12,window.innerWidth-220)+'px';tooltip.style.top=Math.min(y+15,window.innerHeight-85)+'px';}
document.addEventListener('pointermove',e=>{const el=e.target.closest('.map-canvas [data-region]');if(el&&!mapDrag?.moved)displayTooltip(el,e.clientX,e.clientY);else tooltip.hidden=true;});
document.addEventListener('focusin',e=>{const r=e.target.closest('.map-canvas [data-region]');if(r){const b=r.getBoundingClientRect();displayTooltip(r,b.x+b.width/2,b.y+b.height);}});
document.addEventListener('focusout',()=>tooltip.hidden=true);
document.addEventListener('input',e=>{const t=e.target;if(t.id==='region-search'){mapSearch=t.value.trim();document.querySelector('#directory-results').innerHTML=directory();}else if(t.id==='post-search'){listSearch=t.value;document.querySelector('#essay-results').innerHTML=essayResults();}else if(t.id==='picker-search'){const query=t.value.trim();document.querySelectorAll('[data-picker-name]').forEach(el=>el.hidden=!el.dataset.pickerName.includes(query));}else if(t.id==='admin-region-search'){document.querySelectorAll('[data-region-row]').forEach(el=>el.hidden=!el.dataset.regionRow.includes(t.value.trim()));}else if(t.closest('#post-form')){delete t.closest('#post-form').dataset.operationId;editorDirty=true;const hint=document.querySelector('#save-hint');if(hint)hint.textContent='有未保存的修改';}else if(t.dataset.colorId){state.colors[t.dataset.colorId]=t.value;trackMap(t.dataset.colorId);}});
let processingPhotos=0;
document.addEventListener('change',async e=>{const t=e.target;
  if(t.id==='show-labels'){mapLabelsVisible=t.checked;document.querySelectorAll('.map-canvas').forEach(el=>el.classList.toggle('hide-labels',!t.checked));}
  else if(t.dataset.statusId){state.visits[t.dataset.statusId]=t.value;document.querySelector(`[data-color-id="${t.dataset.statusId}"]`).value=colorFor(t.dataset.statusId);trackMap(t.dataset.statusId);}
  else if(t.name==='regions')document.querySelector('#selected-regions').textContent='已选择 '+document.querySelectorAll('[name="regions"]:checked').length+' 个地区';
  else if(t.name==='type')document.querySelector('.travel-region-field').style.opacity=t.value==='essay'?'.6':'1';
  else if(t.id==='photo-upload'){await handlePhotos(t.files);t.value='';}
  else if(t.id==='import-backup'){try{if(!t.files[0])return;if(t.files[0].size>20*1024*1024)throw new Error();const data=JSON.parse(await t.files[0].text());const posts=data.version===2&&data.content?[...data.content.posts,...(data.drafts||[])]:data.posts;if(!Array.isArray(posts))throw new Error();offerImport(posts);}catch{toast('备份格式无效，请选择本博客导出的 JSON 文件');}t.value='';}
});
document.addEventListener('paste',e=>{if(e.target.closest('#rich-editor')){e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'));}});
async function handlePhotos(files){const form=document.querySelector('#post-form');delete form.dataset.operationId;editorDirty=true;processingPhotos++;try{toast('正在处理照片…');for(const file of files){if(!form.isConnected)return;if(editorAttachments.length>=8){toast('最多添加 8 张照片');break;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('请选择 JPG、PNG 或 WebP 照片');continue;}if(file.size>8*1024*1024){toast('每张照片不能超过 8 MB');continue;}try{const src=await compressPhoto(file);if(!form.isConnected)return;editorAttachments.push({type:'image',src,alt:file.name.replace(/\.[^.]+$/,'')});}catch{toast('有一张照片无法读取，请换一张试试');}}if(form.isConnected){document.querySelector('#attachments').innerHTML=attachmentsHTML();toast('照片已添加，点击发布后上传到 GitHub');}}finally{processingPhotos--;}}
function compressPhoto(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{try{const scale=Math.min(1,1400/img.width,1400/img.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.78));}catch(error){reject(error);}finally{URL.revokeObjectURL(url);}};img.onerror=()=>{URL.revokeObjectURL(url);reject();};img.src=url;});}
function extractEditor(){const editor=document.querySelector('#rich-editor');return [...editor.childNodes].map(node=>{if(node.nodeType===Node.TEXT_NODE)return node.textContent.trim()?{type:'p',text:node.textContent}:null;const tag=node.tagName?.toLowerCase();return {type:tag==='h2'?'h2':tag==='blockquote'?'quote':'p',html:sanitizeInline(node.innerHTML||''),text:node.textContent||''};}).filter(b=>b&&(b.text.trim()||b.html?.includes('<br>')));}
async function submitPost(form,intent){if(processingPhotos){toast('照片仍在处理，请稍候');return;}const data=new FormData(form),existing=postForEdit(form.dataset.id),body=[...extractEditor(),...editorAttachments];const post={id:existing?.id||'note-'+crypto.randomUUID(),title:String(data.get('title')).trim(),excerpt:String(data.get('excerpt')).trim(),type:data.get('type'),regions:data.get('type')==='travel'?data.getAll('regions'):[],date:data.get('date'),cover:editorAttachments[0]?.src||existing?.cover||'assets/desk.svg',body,status:intent};const error=validatePost(post);if(error){toast(error);return;}if(!post.excerpt)post.excerpt=body.filter(b=>b.text).map(b=>b.text).join(' ').slice(0,110);form.dataset.id=post.id;
  if(intent==='draft'){if(rememberDraft(post)){editorDirty=false;toast('草稿已保存在本机，尚未上传');go('/preview/'+post.id);}return;}
  if(!session||!repository){toast('请先连接 GitHub');return;}
  // Keep a private recovery copy before touching the network.
  const operationId=form.dataset.operationId||crypto.randomUUID();form.dataset.operationId=operationId;const hasRecovery=rememberDraft(post,operationId);setBusy(true);const hint=document.querySelector('#save-hint');if(hint)hint.textContent='正在上传照片并提交 GitHub…';
  try{const result=await repository.publishPost(post,{expected:editorBasePost,operationId});adoptSite(result.site);drafts=drafts.filter(p=>p.id!==post.id);persistDrafts();editorDirty=false;lastCommit={sha:result.sha,revision:result.site.posts.find(p=>p.id===post.id).version,kind:'post',id:post.id,live:false};saving=false;go('/post/'+post.id);toast('文章与照片已保存到 GitHub');}
  catch(error){toast(error.message);if(hint)hint.textContent=hasRecovery?'尚未提交成功 · 本机草稿已保留，可重试':'尚未提交成功 · 内容仍在本页，请减少照片或导出备份';}
  finally{setBusy(false);}
}
document.addEventListener('submit',async e=>{
  if(e.target.id==='github-login'){e.preventDefault();const form=e.target,field=form.elements.token,token=field.value.trim(),remember=form.elements.remember.checked;field.value='';setBusy(true);const err=document.querySelector('#login-error');err.textContent='正在核对 GitHub 账号和仓库…';try{await connectRepository(token,remember);let target=currentRoute.startsWith('/admin/')?currentRoute:'/admin';try{target=sessionStorage.getItem('fieldnotes-return')||target;sessionStorage.removeItem('fieldnotes-return');}catch{}if(target===currentRoute)render();else go(target);toast('已连接 GitHub，可以发布文章和足迹');}catch(error){err.textContent=error.message;}finally{setBusy(false);}}
  else if(e.target.id==='status-form'){e.preventDefault();const data=new FormData(e.target),id=e.target.dataset.id;await saveMapChanges([{id,status:data.get('status'),color:data.has('custom')?data.get('color'):null,expected:mapValue(repositoryState,id)}]);}
  else if(e.target.id==='post-form'){e.preventDefault();if(saving)return;await submitPost(e.target,e.submitter?.value||'draft');}
});
window.addEventListener('beforeunload',e=>{if(editorDirty||mapEdits.size||saving){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{if(ready)render();});
async function boot(){ready=false;main.innerHTML='<div class="empty-state"><h3>正在打开你的山海地图…</h3><p>从网站读取已发布文章与足迹。</p></div>';try{adoptSite(await readPublicContent());ready=true;render();let token;try{token=sessionStorage.getItem(SESSION_TOKEN_KEY);}catch{}if(token){try{await connectRepository(token,true);render();}catch{try{sessionStorage.removeItem(SESSION_TOKEN_KEY);}catch{}toast('GitHub 授权已失效，请重新连接');}}}catch{main.innerHTML='<div class="empty-state"><h3>暂时无法读取博客内容。</h3><p>请检查网络；如果刚刚更新，请等待 Pages 部署完成后重试。</p><button class="button" data-action="retry-load">重新加载</button></div>';}}
boot();
